// 1. Dealing with 'invisible' proxy types from library APIs
struct ProxyResult {
  int value;
  // A proxy might have an implicit conversion to its underlying type
  operator int() const { return value; }
};

ProxyResult complex_calculation() { return {42}; }

auto val1 = complex_calculation(); // val1's type is ProxyResult

// The idiom forces the desired underlying type
auto val2 = static_cast<int>(complex_calculation()); // val2's type is int

// 2. Making intentional narrowing conversions explicit
double get_tolerance() { return 0.001; }

// This implicit conversion might be mistaken for a bug
float tolerance1 = get_tolerance();

// The idiom clearly states the intent to use a lower-precision type
auto tolerance2 = static_cast<float>(get_tolerance());
